  "Scarcity": {"Explanation": "The email uses the word 'urgent' and emphasizes 'immediate action required' to create a sense of urgency, implying that the window for action is narrow and limited."},
  "Authority": {"Explanation": "The sender identifies themselves as a 'Senior Security Analyst at TechX,' a recognized professional title and institutional affiliation, which establishes credibility and trust in the message."},
  "Commitment/Consistency": {"Explanation": "Not present"},
  "Liking": {"Explanation": "The email personalizes the message by referencing Lotte's recent internship in Paris and her participation in the Dutch IT Professionals community, fostering a sense of familiarity and rapport."},
  "Social proof": {"Explanation": "Not present"}
}

