  "Scarcity": {"Explanation": "Not present. The email does not mention limited time, quantity, or opportunity to act."},
  "Authority": {"Explanation": "The email cites Anthony Ingallinella as the Executive Director of the International Executive Guild, a recognized title that establishes credibility and authority. Additionally, the mention of research from professional associations, trade organizations, and referrals from existing members reinforces the legitimacy and expertise of the organization."},
  "Commitment/Consistency": {"Explanation": "Not present. The email does not reference prior behavior or actions of the recipient to create a sense of consistency or pressure to conform."},
  "Liking": {"Explanation": "Not present. The email does not use personalization, flattery, or familiarity to build rapport or trust with the recipient."},
  "Social proof": {"Explanation": "Not present. The email does not reference the actions or behaviors of others (e.g., number of people who have already joined or been included) to influence the recipient's decision."}
}

